// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether decoding is
// currently inside a visible constrained SMILES span, the active constrained
// SMILES prefix (`currentConstrainedOut`), and a simple step counter (`steps`).
// Outside the span it uses short unconstrained chunks so the model can produce
// surrounding text naturally while still detecting a naturally emitted "<<"
// delimiter. If no delimiter is observed, the strategy can explicitly open one
// so the SMILES object is generated under parser control.
// Inside the span, the parser is the hard authority. The strategy inspects the
// parser branching factor with `ValidTokenCount` and uses a narrow-state
// adaptive constrained step with caller-supplied token groups when the grammar
// is tight, and otherwise uses a bounded constrained-symbol step so multiple
// token pieces can be accepted at once. A light repetition penalty discourages
// degenerate loops in long spans. As soon as the parser reports completeness,
// the strategy closes the visible span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span chunk branch, `insideConstrainedOut`
//   stays false unless `stoppedOpen` is true; then `generated` already ends in
//   "<<", and `EnterObservedConstrainedSpan` sets `currentConstrainedOut := []`,
//   which is a valid parser prefix by the method precondition. In the explicit
//   open branch, `OpenConstrainedSpan` likewise enters constrained mode with the
//   empty constrained prefix, so validity holds immediately.
// parser_validity: In the close branch, `CloseConstrainedSpan` exits
//   constrained mode, so `insideConstrainedOut ==> parser.IsValidPrefix(...)`
//   becomes vacuous. In the one-token constrained branch,
//   `AdaptiveConstrainedStep` returns EOS or a parser-valid next token; on the
//   non-EOS path `AppendConstrainedToken` preserves validity of the constrained
//   prefix. In the symbol branch, `ConstrainedSymbolInGenerated` returns a
//   parser-valid `currentOut`, so assigning it to `currentConstrainedOut`
//   preserves the invariant directly.
// progress: In the outside-span chunk branch, `UnconstrainedChunk` consumes
//   `stepsUsed` token-steps and appends at most that many visible tokens, so
//   after `steps := steps + stepsUsed` the bound `|generated| <=
//   |generatedPrefix| + steps` is preserved. In the explicit open and close
//   branches, each helper consumes exactly one token-step and appends at most
//   one visible delimiter, so the bound is preserved.
// progress: In the one-token constrained branch,
//   `AdaptiveConstrainedStep` consumes one token-step; EOS may consume a step
//   without appending, and otherwise `AppendConstrainedToken` appends exactly
//   one token, so visible growth is at most the consumed budget. In the symbol
//   branch, `ConstrainedSymbolInGenerated` may consume several token-steps,
//   including EOS or rejected suffix tokens, but visible growth is at most
//   `stepsUsed`, so updating `steps` by `stepsUsed` preserves the length bound.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var openedExplicitly: bool := false;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if !openedExplicitly {
      var remainingChunk: nat := maxSteps - steps;
      var chunkBudget: nat := if remainingChunk > 2 then 2 else remainingChunk;
      var chunkedGenerated, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
        lm, prompt, generated, chunkBudget, "<<", eosToken
      );
      generated := chunkedGenerated;
      steps := steps + stepsUsed;
      if stoppedEos {
        break;
      } else if stoppedOpen {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
      } else if steps < maxSteps {
        var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
        generated := openedGenerated;
        insideConstrainedOut := openedInside;
        currentConstrainedOut := openedCurrent;
        openedExplicitly := true;
        steps := steps + 1;
      }
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          var enteredGenerated2, enteredInside2, enteredCurrent2 := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := enteredGenerated2;
          insideConstrainedOut := enteredInside2;
          currentConstrainedOut := enteredCurrent2;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

    if validCount <= narrowThreshold {
      var next := eosToken;
      if |currentConstrainedOut| >= 8 {
        next := helpers.SafeRepetitionPenaltyStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
        );
      } else {
        next := helpers.AdaptiveConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
        );
      }
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
      }
    } else {
      var remaining: nat := maxSteps - steps;
      var symbolBudget: nat := if stepTokenBudget == 0 || stepTokenBudget > remaining then remaining else stepTokenBudget;
      var symbolGenerated, symbolCurrent, hitEos, stepsUsed2 := helpers.ConstrainedSymbolInGenerated(
        lm, parser, constrainedPrompt, generated, currentConstrainedOut, symbolBudget, eosToken
      );
      generated := symbolGenerated;
      insideConstrainedOut := true;
      currentConstrainedOut := symbolCurrent;
      steps := steps + stepsUsed2;
      if hitEos {
        break;
      }
    }
  }
}

cost := steps;

